(function() {
    'use strict';

    class InduMedAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'El Territorio es Tuyo';
            this.version = '1.1.0';

            this.TERRITORY_POTENTIAL = {
                bogotaNorte: 6200,
                bogotaSur: 4800,
                costa: 4100,
                ejeCafetero: 3300
            };

            this.IDEAL_REPS = {
                bogotaNorte: 8,
                bogotaSur: 6,
                costa: 5,
                ejeCafetero: 5
            };

            this.COMP_MULTIPLIER = { 1: 0.80, 2: 0.87, 3: 0.93, 4: 1.00, 5: 0.96, 6: 1.06 };
            this.COMP_TURNOVER = { 1: 0.04, 2: 0.07, 3: 0.11, 4: 0.14, 5: 0.20, 6: 0.24 };

            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    briefingKey: 'round1_briefing',
                    panelId: 'round1Panel'
                },
                {
                    titleKey: 'round2_title',
                    briefingKey: 'round2_briefing',
                    panelId: 'round2Panel'
                },
                {
                    titleKey: 'round3_title',
                    briefingKey: 'round3_briefing',
                    panelId: 'round3Panel'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalRevenue: 0,
                    cumulativeQuota: 0,
                    repsRemaining: 24,
                    voluntaryExits: 0,
                    pipelineHealth: 72,
                    complianceScore: 100,
                    newAccounts: 0,
                    trainingLevel: 0,
                    skillFactor: 0.85,
                    compPlan: 4,
                    hunterCount: 4,
                    round1QuotaAvg: 100,
                    andresRetained: true,
                    costaFixed: false,
                    hasPortal: false,
                    ratchetTriggered: false,
                    activeEvent: '',
                    territories: {
                        bogotaNorte: { reps: 8, quota: 100 },
                        bogotaSur: { reps: 6, quota: 100 },
                        costa: { reps: 5, quota: 100 },
                        ejeCafetero: { reps: 5, quota: 100 }
                    },
                    revenueHistory: [],
                    quotaAttHistory: [],
                    retentionHistory: [],
                    pipelineHistory: [],
                    complianceHistory: [],
                    scoreHistory: [],
                    newAccountHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    round: 1,
                    repsBogNorte: 8,
                    repsBogSur: 6,
                    repsCosta: 5,
                    repsEje: 5,
                    quotaBogNorte: 100,
                    quotaBogSur: 100,
                    quotaCosta: 100,
                    quotaEje: 100,
                    compPlan: 4,
                    trainProduct: 50,
                    trainConsultative: 50,
                    trainCRM: 25,
                    trainClinical: 25,
                    hunterCount: 4,
                    andresDecision: 1,
                    costaDecision: 1,
                    kamDecision: 1,
                    complianceDecision: 1,
                    digitalDecision: 1,
                    aTierCount: 12,
                    kamReps: 2,
                    quotaResetStrategy: 1,
                    poachResponse: 1
                };
            }
            this._updateBriefing(state);
            this._setupLiveValidation();
        }

        _setupLiveValidation() {
            var repIds = ['repsBogNorte', 'repsBogSur', 'repsCosta', 'repsEje'];
            repIds.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        var sum = 0;
                        repIds.forEach(function(rid) {
                            var inp = document.getElementById(rid);
                            if (inp) sum += parseInt(inp.value) || 0;
                        });
                        var display = document.getElementById('repsSumValue');
                        if (display) {
                            display.textContent = sum;
                            display.style.color = sum === 24 ? '#27ae60' : '#e74c3c';
                        }
                    });
                }
            });

            var trainIds = ['trainProduct', 'trainConsultative', 'trainCRM', 'trainClinical'];
            trainIds.forEach(function(id) {
                var el = document.getElementById(id);
                if (el) {
                    el.addEventListener('input', function() {
                        var sum = 0;
                        trainIds.forEach(function(tid) {
                            var inp = document.getElementById(tid);
                            if (inp) sum += parseInt(inp.value) || 0;
                        });
                        var display = document.getElementById('trainSumValue');
                        if (display) {
                            display.textContent = sum;
                            display.style.color = sum <= 400 ? '#27ae60' : '#e74c3c';
                        }
                    });
                }
            });
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = window.mySimulation ? window.mySimulation.t(round.titleKey) : '';

            var textEl = document.getElementById('briefingText');
            if (textEl) textEl.innerHTML = window.mySimulation ? window.mySimulation.t(round.briefingKey) : '';

            this.ROUNDS.forEach(function(r) {
                var panel = document.getElementById(r.panelId);
                if (panel) panel.style.display = 'none';
            });
            var activePanel = document.getElementById(round.panelId);
            if (activePanel) activePanel.style.display = 'block';

            var eventEl = document.getElementById('eventAlert');
            var eventText = document.getElementById('eventText');
            if (state.domainState && state.domainState.activeEvent && eventEl && eventText) {
                eventEl.style.display = 'block';
                eventText.textContent = window.mySimulation ? window.mySimulation.t(state.domainState.activeEvent) : state.domainState.activeEvent;
            } else if (eventEl) {
                eventEl.style.display = 'none';
            }
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;
            decisions.round = period;

            if (period === 1) {
                var bn = document.getElementById('repsBogNorte');
                var bs = document.getElementById('repsBogSur');
                var co = document.getElementById('repsCosta');
                var ej = document.getElementById('repsEje');
                if (bn) decisions.repsBogNorte = parseInt(bn.value) || 0;
                if (bs) decisions.repsBogSur = parseInt(bs.value) || 0;
                if (co) decisions.repsCosta = parseInt(co.value) || 0;
                if (ej) decisions.repsEje = parseInt(ej.value) || 0;

                var repSum = decisions.repsBogNorte + decisions.repsBogSur + decisions.repsCosta + decisions.repsEje;
                if (repSum !== 24) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('reps_sum_warning'), 'warning'
                    );
                    return false;
                }

                var qbn = document.getElementById('quotaBogNorte');
                var qbs = document.getElementById('quotaBogSur');
                var qco = document.getElementById('quotaCosta');
                var qej = document.getElementById('quotaEje');
                if (qbn) decisions.quotaBogNorte = parseInt(qbn.value) || 100;
                if (qbs) decisions.quotaBogSur = parseInt(qbs.value) || 100;
                if (qco) decisions.quotaCosta = parseInt(qco.value) || 100;
                if (qej) decisions.quotaEje = parseInt(qej.value) || 100;

                var quotas = [decisions.quotaBogNorte, decisions.quotaBogSur, decisions.quotaCosta, decisions.quotaEje];
                for (var q = 0; q < quotas.length; q++) {
                    if (quotas[q] < 80 || quotas[q] > 120) {
                        window.mySimulation.uiManager.showNotification(
                            window.mySimulation.t('quota_range_warning'), 'warning'
                        );
                        return false;
                    }
                }

                var cp = document.getElementById('compPlan');
                if (cp) decisions.compPlan = parseInt(cp.value) || 4;

                var tp = document.getElementById('trainProduct');
                var tc = document.getElementById('trainConsultative');
                var tr = document.getElementById('trainCRM');
                var tl = document.getElementById('trainClinical');
                if (tp) decisions.trainProduct = parseInt(tp.value) || 0;
                if (tc) decisions.trainConsultative = parseInt(tc.value) || 0;
                if (tr) decisions.trainCRM = parseInt(tr.value) || 0;
                if (tl) decisions.trainClinical = parseInt(tl.value) || 0;

                var trainSum = decisions.trainProduct + decisions.trainConsultative + decisions.trainCRM + decisions.trainClinical;
                if (trainSum > 400) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('training_sum_warning'), 'warning'
                    );
                    return false;
                }

                var hc = document.getElementById('hunterCount');
                if (hc) decisions.hunterCount = parseInt(hc.value) || 4;
                if (decisions.hunterCount < 2 || decisions.hunterCount > 8) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('hunter_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var ad = document.getElementById('andresDecision');
                var cd = document.getElementById('costaDecision');
                var kd = document.getElementById('kamDecision');
                var cpd = document.getElementById('complianceDecision');
                var dd = document.getElementById('digitalDecision');
                if (ad) decisions.andresDecision = parseInt(ad.value) || 1;
                if (cd) decisions.costaDecision = parseInt(cd.value) || 1;
                if (kd) decisions.kamDecision = parseInt(kd.value) || 1;
                if (cpd) decisions.complianceDecision = parseInt(cpd.value) || 1;
                if (dd) decisions.digitalDecision = parseInt(dd.value) || 1;
            } else if (period === 3) {
                var at = document.getElementById('aTierCount');
                var kr = document.getElementById('kamReps');
                var qr = document.getElementById('quotaResetStrategy');
                var pr = document.getElementById('poachResponse');
                if (at) decisions.aTierCount = parseInt(at.value) || 12;
                if (kr) decisions.kamReps = parseInt(kr.value) || 2;
                if (qr) decisions.quotaResetStrategy = parseInt(qr.value) || 1;
                if (pr) decisions.poachResponse = parseInt(pr.value) || 1;

                if (decisions.aTierCount < 5 || decisions.aTierCount > 20) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('a_tier_warning'), 'warning'
                    );
                    return false;
                }
                if (decisions.kamReps < 1 || decisions.kamReps > 4) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('kam_reps_warning'), 'warning'
                    );
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        _quotaMotivation(quotaPct) {
            if (quotaPct >= 95 && quotaPct <= 105) return 0.96;
            if (quotaPct >= 90 && quotaPct < 95) return 0.89;
            if (quotaPct >= 80 && quotaPct < 90) return 0.82;
            if (quotaPct > 105 && quotaPct <= 110) return 0.87;
            if (quotaPct > 110 && quotaPct <= 115) return 0.76;
            return 0.65;
        }

        _coverageFactor(reps, ideal) {
            var ratio = reps / ideal;
            if (ratio <= 1) return 0.70 + 0.30 * ratio;
            return 1.0 + 0.08 * Math.log(ratio);
        }

        _rollEvent(round) {
            var roll = window.mySimulation.adapter._rng() * 100;
            if (round === 1) {
                if (roll < 40) return 'event_procurement';
            } else if (round === 2) {
                if (roll < 30) return 'event_liquidation';
                if (roll < 55) return 'event_medsupply_recruit';
            } else if (round === 3) {
                if (roll < 60) return 'event_insurance_expansion';
            }
            return '';
        }

        _seedRng(seed) { this._rngState = ((seed >>> 0) || 1) >>> 0; }
        _rng() {
            this._rngState = (this._rngState + 0x6D2B79F5) >>> 0;
            var t = this._rngState;
            t = Math.imul(t ^ (t >>> 15), t | 1) >>> 0;
            t = (t ^ (t + Math.imul(t ^ (t >>> 7), t | 61))) >>> 0;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        }
        _hashSeed(period, dec) {
            var s = 'p' + period;
            var keys = Object.keys(dec).sort();
            for (var i = 0; i < keys.length; i++) { s += '|' + keys[i] + '=' + dec[keys[i]]; }
            var h = 2166136261 >>> 0;
            for (var c = 0; c < s.length; c++) { h = Math.imul(h ^ s.charCodeAt(c), 16777619) >>> 0; }
            return h >>> 0;
        }
        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            this._seedRng(this._hashSeed(period, d));
            var event = this._rollEvent(period);
            ds.activeEvent = event;

            var roundRevenue = 0;
            var roundQuota = 0;
            var roundExits = 0;
            var roundNewAccounts = 0;
            var pipelineDelta = 0;
            var complianceDelta = 0;

            if (period === 1) {
                ds.territories.bogotaNorte = { reps: d.repsBogNorte, quota: d.quotaBogNorte };
                ds.territories.bogotaSur = { reps: d.repsBogSur, quota: d.quotaBogSur };
                ds.territories.costa = { reps: d.repsCosta, quota: d.quotaCosta };
                ds.territories.ejeCafetero = { reps: d.repsEje, quota: d.quotaEje };
                ds.compPlan = d.compPlan;
                ds.hunterCount = d.hunterCount;

                var trainTotal = d.trainProduct + d.trainConsultative + d.trainCRM + d.trainClinical;
                ds.trainingLevel = trainTotal;
                ds.skillFactor = 0.85 + (trainTotal / 400) * 0.10;

                var compMult = this.COMP_MULTIPLIER[d.compPlan] || 1.0;
                var territories = ['bogotaNorte', 'bogotaSur', 'costa', 'ejeCafetero'];
                var self = this;

                territories.forEach(function(t) {
                    var pot = self.TERRITORY_POTENTIAL[t];
                    var ideal = self.IDEAL_REPS[t];
                    var reps = ds.territories[t].reps;
                    var quotaPct = ds.territories[t].quota;

                    var coverage = self._coverageFactor(reps, ideal);
                    var motivation = self._quotaMotivation(quotaPct);
                    var noise = 0.92 + window.mySimulation.adapter._rng() * 0.16;

                    var costaDebuff = (t === 'costa') ? 0.82 : 1.0;
                    var annualRev = pot * coverage * motivation * compMult * ds.skillFactor * costaDebuff * noise;
                    var quarterRev = annualRev / 4;

                    roundRevenue += quarterRev;
                    roundQuota += (pot * quotaPct / 100) / 4;
                });

                var baseTurnover = this.COMP_TURNOVER[d.compPlan] || 0.14;
                var avgQuota = (d.quotaBogNorte + d.quotaBogSur + d.quotaCosta + d.quotaEje) / 4;
                ds.round1QuotaAvg = avgQuota;
                var quotaPenalty = Math.abs(avgQuota - 100) * 0.003;
                var turnoverProb = baseTurnover + quotaPenalty - (trainTotal / 400) * 0.05;
                roundExits = Math.round(24 * Math.max(0, Math.min(turnoverProb, 0.35)));

                roundNewAccounts = Math.round(d.hunterCount * (1.5 + window.mySimulation.adapter._rng() * 1.5));
                pipelineDelta = (d.hunterCount - 4) * 3 + (d.trainConsultative / 50) * 2 + roundNewAccounts * 0.5 - 5;

                if (event === 'event_procurement') {
                    roundRevenue *= 0.88;
                    pipelineDelta -= 8;
                }

            } else if (period === 2) {
                var compMult2 = this.COMP_MULTIPLIER[ds.compPlan] || 1.0;
                var territories2 = ['bogotaNorte', 'bogotaSur', 'costa', 'ejeCafetero'];
                var self2 = this;

                if (d.andresDecision === 1) {
                    ds.andresRetained = true;
                } else if (d.andresDecision === 2) {
                    ds.andresRetained = window.mySimulation.adapter._rng() > 0.2;
                } else {
                    ds.andresRetained = window.mySimulation.adapter._rng() > 0.6;
                }

                var costaBoost = 1.0;
                if (d.costaDecision === 1) {
                    costaBoost = 1.10;
                    ds.costaFixed = true;
                } else if (d.costaDecision === 2) {
                    costaBoost = 0.85;
                    roundExits += 2;
                } else {
                    costaBoost = 1.18;
                    ds.costaFixed = true;
                }

                var kamRevBonus = 0;
                if (d.kamDecision === 1) {
                    kamRevBonus = 320 + window.mySimulation.adapter._rng() * 180;
                } else if (d.kamDecision === 2) {
                    kamRevBonus = 80 + window.mySimulation.adapter._rng() * 120;
                } else {
                    kamRevBonus = 220 + window.mySimulation.adapter._rng() * 160;
                }

                territories2.forEach(function(t) {
                    var pot = self2.TERRITORY_POTENTIAL[t];
                    var reps = ds.territories[t].reps;
                    var ideal = self2.IDEAL_REPS[t];
                    var quotaPct = ds.territories[t].quota;
                    var coverage = self2._coverageFactor(reps, ideal);
                    var motivation = self2._quotaMotivation(quotaPct);
                    var noise = 0.93 + window.mySimulation.adapter._rng() * 0.14;
                    var costaAdj = (t === 'costa') ? costaBoost * 0.82 : 1.0;
                    var annualRev = pot * coverage * motivation * compMult2 * ds.skillFactor * costaAdj * noise;
                    var quarterRev = annualRev / 4;
                    roundRevenue += quarterRev;
                    roundQuota += (pot * ds.territories[t].quota / 100) / 4;
                });

                roundRevenue += kamRevBonus;

                if (!ds.andresRetained) {
                    roundRevenue *= 0.93;
                    roundExits += 1;
                }

                if (d.complianceDecision === 1) {
                    complianceDelta = -5;
                } else if (d.complianceDecision === 2) {
                    complianceDelta = 5;
                } else {
                    complianceDelta = 15;
                    roundExits += 2;
                }

                if (d.digitalDecision === 1) {
                    ds.hasPortal = true;
                    pipelineDelta += 10;
                    roundNewAccounts += 3;
                } else {
                    pipelineDelta += 5;
                    roundNewAccounts += 1;
                }

                roundNewAccounts += Math.round(2 + window.mySimulation.adapter._rng() * 3);

                if (event === 'event_liquidation') {
                    roundRevenue *= 0.90;
                    roundNewAccounts = Math.max(0, roundNewAccounts - 3);
                } else if (event === 'event_medsupply_recruit') {
                    roundRevenue *= 1.04;
                    roundNewAccounts += 3;
                    pipelineDelta += 5;
                }

            } else if (period === 3) {
                var compMult3 = this.COMP_MULTIPLIER[ds.compPlan] || 1.0;
                var territories3 = ['bogotaNorte', 'bogotaSur', 'costa', 'ejeCafetero'];
                var self3 = this;

                var kamCovPenalty = d.kamReps * 0.02;
                var kamRevMult = 1.0 + (d.aTierCount / 340) * 0.5 * (d.kamReps / 2);

                var ratchetPenalty = 1.0;
                if (d.quotaResetStrategy === 3) {
                    ds.ratchetTriggered = true;
                    ratchetPenalty = 0.85;
                } else if (d.quotaResetStrategy === 2) {
                    ratchetPenalty = 0.95;
                } else {
                    ratchetPenalty = 1.02;
                }

                territories3.forEach(function(t) {
                    var pot = self3.TERRITORY_POTENTIAL[t];
                    var reps = ds.territories[t].reps;
                    var ideal = self3.IDEAL_REPS[t];
                    var quotaPct = ds.territories[t].quota;
                    var coverage = self3._coverageFactor(reps, ideal) - kamCovPenalty;
                    var motivation = self3._quotaMotivation(quotaPct) * ratchetPenalty;
                    var noise = 0.93 + window.mySimulation.adapter._rng() * 0.14;
                    var costaAdj = (t === 'costa' && ds.costaFixed) ? 0.95 : (t === 'costa' ? 0.78 : 1.0);
                    var annualRev = pot * coverage * motivation * compMult3 * ds.skillFactor * costaAdj * noise;
                    var quarterRev = annualRev / 4;
                    roundRevenue += quarterRev;
                    roundQuota += (pot * quotaPct / 100) / 4;
                });

                roundRevenue *= kamRevMult;

                var poachExits = 0;
                if (d.poachResponse === 1) {
                    poachExits = 0;
                    roundRevenue *= 0.97;
                } else if (d.poachResponse === 2) {
                    poachExits = window.mySimulation.adapter._rng() > 0.7 ? 1 : 0;
                } else {
                    poachExits = 2 + (window.mySimulation.adapter._rng() > 0.5 ? 1 : 0);
                    roundRevenue *= 0.91;
                }
                roundExits += poachExits;

                if (ds.hasPortal) {
                    roundNewAccounts += 4;
                    pipelineDelta += 6;
                }

                roundNewAccounts += Math.round(ds.hunterCount * (1.0 + window.mySimulation.adapter._rng()));

                if (event === 'event_insurance_expansion') {
                    roundRevenue *= 1.12;
                    roundNewAccounts += 5;
                    pipelineDelta += 10;
                }
            }

            roundRevenue = Math.round(roundRevenue);
            ds.totalRevenue += roundRevenue;
            ds.cumulativeQuota += Math.round(roundQuota);
            ds.repsRemaining = Math.max(10, ds.repsRemaining - roundExits);
            ds.voluntaryExits += roundExits;
            ds.newAccounts += roundNewAccounts;
            ds.pipelineHealth = Math.max(20, Math.min(100, ds.pipelineHealth + pipelineDelta));
            ds.complianceScore = Math.max(0, Math.min(100, ds.complianceScore + complianceDelta));

            var quotaAtt = ds.cumulativeQuota > 0 ? Math.round((ds.totalRevenue / ds.cumulativeQuota) * 100) : 0;
            var retentionRate = Math.round((ds.repsRemaining / 24) * 100);
            var turnoverAnnual = Math.round((ds.voluntaryExits / 24) * 100);

            var revenueScore = Math.min(350, Math.round((quotaAtt / 95) * 350));
            var retentionScore = turnoverAnnual <= 15 ? 250 : Math.max(0, 250 - (turnoverAnnual - 15) * 12);
            var pipelineScore = Math.round((ds.pipelineHealth / 100) * 200);
            var newAcctScore = Math.min(100, Math.round((ds.newAccounts / (8 * period)) * 100));
            var compScore = Math.round((ds.complianceScore / 100) * 100);
            var totalScore = revenueScore + retentionScore + pipelineScore + newAcctScore + compScore;

            ds.revenueHistory.push(roundRevenue);
            ds.quotaAttHistory.push(quotaAtt);
            ds.retentionHistory.push(ds.repsRemaining);
            ds.pipelineHistory.push(ds.pipelineHealth);
            ds.complianceHistory.push(ds.complianceScore);
            ds.scoreHistory.push(totalScore);
            ds.newAccountHistory.push(roundNewAccounts);

            var results = {
                period: period,
                revenue: roundRevenue,
                quotaTarget: Math.round(roundQuota),
                quotaAttainment: quotaAtt,
                repsRemaining: ds.repsRemaining,
                exits: roundExits,
                pipelineHealth: ds.pipelineHealth,
                complianceScore: ds.complianceScore,
                newAccounts: roundNewAccounts,
                score: totalScore,
                event: event
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
            }, 500);

            return results;
        }

