        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var totalScore = lastResult.score || 0;
            var totalRevenue = 0;
            var totalNewAccounts = 0;
            history.forEach(function(h) {
                totalRevenue += (h.results && h.results.revenue) || 0;
                totalNewAccounts += (h.results && h.results.newAccounts) || 0;
            });

            var performance = 'Needs Improvement';
            if (totalScore >= 800) performance = 'Excellent Sales Director';
            else if (totalScore >= 650) performance = 'Strong Performance';
            else if (totalScore >= 450) performance = 'Developing Leader';

            var insights = [];
            if (lastResult.quotaAttainment >= 95) {
                insights.push('Strong quota attainment demonstrates effective territory and quota design.');
            } else {
                insights.push('Quota attainment below 95% — review territory balance and quota calibration.');
            }
            if (lastResult.repsRemaining >= 20) {
                insights.push('Good retention — your compensation and management approach keeps talent.');
            } else {
                insights.push('High turnover erodes institutional knowledge and client relationships.');
            }
            if (lastResult.pipelineHealth >= 70) {
                insights.push('Healthy pipeline ensures sustainable revenue in future quarters.');
            } else {
                insights.push('Weak pipeline — increase hunter allocation and prospecting investment.');
            }

            return {
                totalScore: totalScore,
                totalRevenue: totalRevenue,
                totalNewAccounts: totalNewAccounts,
                performance: performance,
                insights: insights
            };
        }

